using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record AndroidResearchSessionSummary(string SessionFingerprint,string PreviewFingerprint,string DatasetFingerprint,string StrategyFingerprint,AndroidResearchQueueState QueueState,string? ResultStatus,bool Terminal,bool CanSubmitOrders);public static class AndroidResearchSessionSummaryRules{public static AndroidResearchSessionSummary Create(AndroidResearchLaunchPreview preview,AndroidResearchQueueItem queue,AndroidResearchResultCard? result=null){if(queue.DraftFingerprint!=preview.DraftFingerprint)throw new InvalidOperationException("Research session queue does not match launch preview.");if(result is not null&&(result.DatasetFingerprint!=queue.DatasetFingerprint||result.StrategyFingerprint!=queue.StrategyFingerprint))throw new InvalidOperationException("Research session result does not match queued identities.");var terminal=queue.State is AndroidResearchQueueState.Complete or AndroidResearchQueueState.Blocked or AndroidResearchQueueState.Invalid;var status=result?.Status.ToString();var text=string.Join("|",preview.PreviewFingerprint,queue.DraftFingerprint,queue.DatasetFingerprint,queue.StrategyFingerprint,queue.State,status??string.Empty,terminal);var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,preview.PreviewFingerprint,queue.DatasetFingerprint,queue.StrategyFingerprint,queue.State,status,terminal,false);}}
